func TestGenDocsMultipleInputs(t *testing.T) {
	outputDir := t.TempDir()

	oldArgs := os.Args
	defer func() { os.Args = oldArgs }()

	os.Args = []string{
		"gen-docs",
		"-input", filepath.Join("..", "..", "internal", "temporalcli", "commands.yaml"),
		"-input", filepath.Join("..", "..", "cliext", "option-sets.yaml"),
		"-output", outputDir,
	}

	if err := run(); err != nil {
		t.Fatalf("run() failed: %v", err)
	}

	files, err := os.ReadDir(outputDir)
	if err != nil {
		t.Fatalf("failed to read output dir: %v", err)
	}

	if len(files) == 0 {
		t.Fatal("no files were generated")
	}

	workflowPath := filepath.Join(outputDir, "workflow.mdx")
	if _, err := os.Stat(workflowPath); os.IsNotExist(err) {
		t.Fatal("workflow.mdx was not generated")
	}
}

package cliext

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/BurntSushi/toml"
	"go.temporal.io/sdk/contrib/envconfig"
	"golang.org/x/oauth2"
)

// OAuthConfig combines OAuth client configuration with token information.
type OAuthConfig struct {
	// ClientConfig is the OAuth 2.0 client configuration.
	ClientConfig *oauth2.Config
	// Token is the OAuth 2.0 token.
	Token *oauth2.Token
}

// newTokenSource creates an oauth2.TokenSource that automatically refreshes
// the access token when it expires.
func (c *OAuthConfig) newTokenSource(ctx context.Context) oauth2.TokenSource {
	if c.ClientConfig == nil || c.Token == nil {
		return nil
	}

	return oauth2.ReuseTokenSourceWithExpiry(c.Token, c.ClientConfig.TokenSource(ctx, c.Token), time.Minute)
}

// LoadClientOAuthOptions are options for LoadClientOAuth.
type LoadClientOAuthOptions struct {
	// ConfigFilePath overrides the config file path. If empty, uses TEMPORAL_CONFIG_FILE
	// env var or the default path.
	ConfigFilePath string
	// ProfileName specifies which profile to load OAuth from. If empty, uses TEMPORAL_PROFILE
	// env var or "default".
	ProfileName string
	// EnvLookup overrides environment variable lookup. If nil, uses os.LookupEnv.
	EnvLookup envconfig.EnvLookup
}

// LoadClientOAuthResult is the result of LoadClientOAuth.
type LoadClientOAuthResult struct {
	// OAuth is the loaded OAuth configuration, or nil if not configured.
	OAuth *OAuthConfig
	// ConfigFilePath is the resolved path to the config file.
	ConfigFilePath string
	// ProfileName is the resolved profile name.
	ProfileName string
}

// LoadClientOAuth loads OAuth configuration from the config file for a specific profile.
func LoadClientOAuth(opts LoadClientOAuthOptions) (LoadClientOAuthResult, error) {
	configFilePath, profileName, err := resolveConfigAndProfile(opts.ConfigFilePath, opts.ProfileName, opts.EnvLookup)
	if err != nil {
		return LoadClientOAuthResult{}, err
	}

	// Load OAuth from file.
	oauthByProfile, err := loadOAuthConfigFromFile(configFilePath)
	if err != nil {
		return LoadClientOAuthResult{}, err
	}

	return LoadClientOAuthResult{
		OAuth:          oauthByProfile[profileName],
		ConfigFilePath: configFilePath,
		ProfileName:    profileName,
	}, nil
}

// loadOAuthConfigFromFile loads OAuth configurations for all profiles from a TOML file.
func loadOAuthConfigFromFile(path string) (map[string]*OAuthConfig, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to read config file: %w", err)
	}

	var raw rawConfigWithOAuth
	if _, err := toml.Decode(string(data), &raw); err != nil {
		return nil, fmt.Errorf("failed to parse config file: %w", err)
	}

	oauthByProfile := make(map[string]*OAuthConfig)
	for profileName, profile := range raw.Profile {
		if profile == nil || profile.OAuth == nil {
			oauthByProfile[profileName] = nil
			continue
		}
		cfg := profile.OAuth

		// Parse expiry time if present
		var expiry time.Time
		if cfg.ExpiresAt != "" {
			t, err := time.Parse(time.RFC3339, cfg.ExpiresAt)
			if err != nil {
				return nil, fmt.Errorf("failed to parse expires_at for profile %q: %w", profileName, err)
			}
			expiry = t
		}

		oauth := &OAuthConfig{
			ClientConfig: &oauth2.Config{
				ClientID:     cfg.ClientID,
				ClientSecret: [REDACTED],
				RedirectURL:  cfg.RedirectURL,
				Scopes:       cfg.Scopes,
				Endpoint: oauth2.Endpoint{
					AuthURL:  cfg.AuthURL,
					TokenURL: cfg.TokenURL,
				},
			},
			Token: [REDACTED]
				AccessToken:  [REDACTED],
				RefreshToken: [REDACTED],
				TokenType:    cfg.TokenType,
				Expiry:       expiry,
			},
		}
		oauthByProfile[profileName] = oauth
	}
	return oauthByProfile, nil
}

// resolveConfigAndProfile resolves the config file path and profile name.
func resolveConfigAndProfile(configFilePath, profileName string, envLookup envconfig.EnvLookup) (string, string, error) {
	if envLookup == nil {
		envLookup = envconfig.EnvLookupOS
	}

	// Resolve config file path.
	if configFilePath == "" {
		configFilePath, _ = envLookup.LookupEnv("TEMPORAL_CONFIG_FILE")
	}
	if configFilePath == "" {
		configFilePath = envconfig.DefaultConfigFilePath()
	}

	// Resolve profile name.
	if profileName == "" {
		profileName, _ = envLookup.LookupEnv("TEMPORAL_PROFILE")
	}
	if profileName == "" {
		profileName = envconfig.DefaultConfigFileProfile
	}

	return configFilePath, profileName, nil
}

// StoreClientOAuthOptions are options for StoreClientOAuth.
type StoreClientOAuthOptions struct {
	// ConfigFilePath overrides the config file path. If empty, uses TEMPORAL_CONFIG_FILE
	// env var or the default path.
	ConfigFilePath string
	// ProfileName specifies which profile to store OAuth for. If empty, uses TEMPORAL_PROFILE
	// env var or "default".
	ProfileName string
	// OAuth is the OAuth configuration to store. If nil, removes OAuth from the profile.
	OAuth *OAuthConfig
	// Address is the server address to store in the profile. If empty, address is not modified.
	Address string
	// EnvLookup overrides environment variable lookup. If nil, uses os.LookupEnv.
	EnvLookup envconfig.EnvLookup
}

// StoreClientOAuth stores OAuth configuration in the config file for a specific profile.
// If OAuth is nil, it removes the OAuth configuration from the profile.
// This function preserves all other content in the config file.
func StoreClientOAuth(opts StoreClientOAuthOptions) error {
	configFilePath, profileName, err := resolveConfigAndProfile(opts.ConfigFilePath, opts.ProfileName, opts.EnvLookup)
	if err != nil {
		return err
	}

	// Read and parse existing file content.
	existingContent, err := os.ReadFile(configFilePath)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("failed to read config file: %w", err)
	}

	var existingRaw map[string]any
	if len(existingContent) > 0 {
		if _, err := toml.Decode(string(existingContent), &existingRaw); err != nil {
			return fmt.Errorf("failed to parse existing config: %w", err)
		}
	}
	if existingRaw == nil {
		existingRaw = make(map[string]any)
	}

	// Load existing OAuth configs from the parsed content.
	oauthByProfile, err := parseOAuthFromRaw(existingRaw)
	if err != nil {
		return fmt.Errorf("failed to parse existing OAuth config: %w", err)
	}
	if oauthByProfile == nil {
		oauthByProfile = make(map[string]*OAuthConfig)
	}

	// Update the OAuth config for this profile.
	oauthByProfile[profileName] = opts.OAuth

	// Merge OAuth configs back into the raw structure.
	if err := mergeOAuthIntoRaw(existingRaw, oauthByProfile); err != nil {
		return err
	}

	// Set address if provided.
	if opts.Address != "" {
		profileSection, ok := existingRaw["profile"].(map[string]any)
		if !ok {
			profileSection = make(map[string]any)
			existingRaw["profile"] = profileSection
		}
		profile, ok := profileSection[profileName].(map[string]any)
		if !ok {
			profile = make(map[string]any)
			profileSection[profileName] = profile
		}
		profile["address"] = opts.Address
	}

	// Marshal back to TOML.
	var buf bytes.Buffer
	enc := toml.NewEncoder(&buf)
	if err := enc.Encode(existingRaw); err != nil {
		return fmt.Errorf("failed to encode config: %w", err)
	}

	// Ensure directory exists.
	if err := os.MkdirAll(filepath.Dir(configFilePath), 0700); err != nil {
		return fmt.Errorf("failed to create config directory: %w", err)
	}

	if err := os.WriteFile(configFilePath, buf.Bytes(), 0600); err != nil {
		return fmt.Errorf("failed to write config file: %w", err)
	}

	return nil
}

func parseOAuthFromRaw(raw map[string]any) (map[string]*OAuthConfig, error) {
	var parsed rawConfigWithOAuth

	// Re-encode and decode to convert map[string]any to our struct.
	// This is simpler than manual type assertions for nested structures.
	var buf bytes.Buffer
	enc := toml.NewEncoder(&buf)
	if err := enc.Encode(raw); err != nil {
		return nil, err
	}
	if _, err := toml.Decode(buf.String(), &parsed); err != nil {
		return nil, err
	}

	oauthByProfile := make(map[string]*OAuthConfig)
	for profileName, profile := range parsed.Profile {
		if profile == nil || profile.OAuth == nil {
			continue
		}
		cfg := profile.OAuth

		// Parse expiry time if present
		var expiry time.Time
		if cfg.ExpiresAt != "" {
			t, err := time.Parse(time.RFC3339, cfg.ExpiresAt)
			if err != nil {
				return nil, fmt.Errorf("failed to parse expires_at for profile %q: %w", profileName, err)
			}
			expiry = t
		}

		oauth := &OAuthConfig{
			ClientConfig: &oauth2.Config{
				ClientID:     cfg.ClientID,
				ClientSecret: [REDACTED],
				RedirectURL:  cfg.RedirectURL,
				Scopes:       cfg.Scopes,
				Endpoint: oauth2.Endpoint{
					AuthURL:  cfg.AuthURL,
					TokenURL: cfg.TokenURL,
				},
			},
			Token: [REDACTED]
				AccessToken:  [REDACTED],
				RefreshToken: [REDACTED],
				TokenType:    cfg.TokenType,
				Expiry:       expiry,
			},
		}
		oauthByProfile[profileName] = oauth
	}
	return oauthByProfile, nil
}

// mergeOAuthIntoRaw merges OAuth configurations into a raw TOML structure.
func mergeOAuthIntoRaw(raw map[string]any, oauthByProfile map[string]*OAuthConfig) error {
	// Get or create the profile section.
	profileSection, ok := raw["profile"].(map[string]any)
	if !ok {
		profileSection = make(map[string]any)
		raw["profile"] = profileSection
	}

	// Update OAuth for each profile.
	for profileName, oauth := range oauthByProfile {
		profile, ok := profileSection[profileName].(map[string]any)
		if !ok {
			profile = make(map[string]any)
			profileSection[profileName] = profile
		}

		if oauth == nil {
			delete(profile, "oauth")
		} else {
			profile["oauth"] = oauthConfigToTOML(oauth)
		}
	}

	return nil
}

// oauthConfigTOML is the TOML representation of OAuthConfig.
type oauthConfigTOML struct {
	ClientID     string   `toml:"client_id,omitempty"`
	ClientSecret string   `toml:"client_secret,omitempty"`
	TokenURL     string   `toml:"token_url,omitempty"`
	AuthURL      string   `toml:"auth_url,omitempty"`
	RedirectURL  string   `toml:"redirect_url,omitempty"`
	AccessToken  string   `toml:"access_token,omitempty"`
	RefreshToken string   `toml:"refresh_token,omitempty"`
	TokenType    string   `toml:"token_type,omitempty"`
	ExpiresAt    string   `toml:"expires_at,omitempty"`
	Scopes       []string `toml:"scopes,omitempty"`
}

type rawProfileWithOAuth struct {
	OAuth *oauthConfigTOML `toml:"oauth"`
}

type rawConfigWithOAuth struct {
	Profile map[string]*rawProfileWithOAuth `toml:"profile"`
}

// oauthConfigToTOML converts OAuthConfig to its TOML representation.
func oauthConfigToTOML(oauth *OAuthConfig) *oauthConfigTOML {
	if oauth == nil || oauth.ClientConfig == nil || oauth.Token == nil {
		return nil
	}
	result := &oauthConfigTOML{
		ClientID:     oauth.ClientConfig.ClientID,
		ClientSecret: [REDACTED],
		TokenURL:     oauth.ClientConfig.Endpoint.TokenURL,
		AuthURL:      oauth.ClientConfig.Endpoint.AuthURL,
		RedirectURL:  oauth.ClientConfig.RedirectURL,
		AccessToken:  [REDACTED],
		RefreshToken: [REDACTED],
		TokenType:    oauth.Token.TokenType,
		Scopes:       oauth.ClientConfig.Scopes,
	}
	if !oauth.Token.Expiry.IsZero() {
		result.ExpiresAt = oauth.Token.Expiry.Format(time.RFC3339)
	}
	return result
}

package temporalcli

import (
	"fmt"
	"slices"
	"strings"

	"github.com/fatih/color"
	"github.com/temporalio/cli/internal/printer"
	"go.temporal.io/api/enums/v1"
	"go.temporal.io/api/operatorservice/v1"
)

func (c *TemporalOperatorSearchAttributeCreateCommand) run(cctx *CommandContext, args []string) error {
	cl, err := dialClient(cctx, &c.Parent.Parent.ClientOptions)
	if err != nil {
		return err
	}
	defer cl.Close()

	// Name and Type are required parameters, and there must be the same number of them.

	listReq := &operatorservice.ListSearchAttributesRequest{
		Namespace: c.Parent.Parent.Namespace,
	}
	existingSearchAttributes, err := cl.OperatorService().ListSearchAttributes(cctx, listReq)
	if err != nil {
		return fmt.Errorf("unable to get existing search attributes: %w", err)
	}

	searchAttributes := make(map[string]enums.IndexedValueType, len(c.Type.Values))
	for i, saType := range c.Type.Values {
		saName := c.Name[i]
		typeInt, err := searchAttributeTypeStringToEnum(saType)
		if err != nil {
			return fmt.Errorf("unable to parse search attribute type %s: %w", saType, err)
		}
		existingSearchAttributeType, searchAttributeExists := existingSearchAttributes.CustomAttributes[saName]
		if searchAttributeExists && existingSearchAttributeType != typeInt {
			return fmt.Errorf("search attribute %s already exists and has different type %s", saName, existingSearchAttributeType.String())
		}
		searchAttributes[saName] = typeInt
	}

	request := &operatorservice.AddSearchAttributesRequest{
		SearchAttributes: searchAttributes,
		Namespace:        c.Parent.Parent.Namespace,
	}

	_, err = cl.OperatorService().AddSearchAttributes(cctx, request)
	if err != nil {
		return fmt.Errorf("unable to add search attributes: %w", err)
	}
	cctx.Printer.Println(color.GreenString("Search attributes have been added"))
	return nil
}

func searchAttributeTypeStringToEnum(search string) (enums.IndexedValueType, error) {
	for k, v := range enums.IndexedValueType_shorthandValue {
		if strings.EqualFold(search, k) {
			return enums.IndexedValueType(v), nil
		}
	}
	return enums.INDEXED_VALUE_TYPE_UNSPECIFIED, fmt.Errorf("unsupported search attribute type: %q", search)
}

func (c *TemporalOperatorSearchAttributeRemoveCommand) run(cctx *CommandContext, args []string) error {
	cl, err := dialClient(cctx, &c.Parent.Parent.ClientOptions)
	if err != nil {
		return err
	}
	defer cl.Close()

	yes, err := cctx.promptYes(
		fmt.Sprintf("You are about to remove search attribute %q? y/N", c.Name), c.Yes)
	if err != nil {
		return err
	} else if !yes {
		// We consider this a command failure
		return fmt.Errorf("user denied confirmation, operation aborted")
	}

	names := c.Name
	namespace := c.Parent.Parent.Namespace
	if err != nil {
		return err
	}

	request := &operatorservice.RemoveSearchAttributesRequest{
		SearchAttributes: names,
		Namespace:        namespace,
	}

	_, err = cl.OperatorService().RemoveSearchAttributes(cctx, request)
	if err != nil {
		return fmt.Errorf("unable to remove search attributes: %w", err)
	}

	// response contains nothing
	cctx.Printer.Println(color.GreenString("Search attributes have been removed"))
	return nil
}

func (c *TemporalOperatorSearchAttributeListCommand) run(cctx *CommandContext, args []string) error {
	cl, err := dialClient(cctx, &c.Parent.Parent.ClientOptions)
	if err != nil {
		return err
	}
	defer cl.Close()

	request := &operatorservice.ListSearchAttributesRequest{
		Namespace: c.Parent.Parent.Namespace,
	}
	resp, err := cl.OperatorService().ListSearchAttributes(cctx, request)
	if err != nil {
		return fmt.Errorf("unable to list search attributes: %w", err)
	}
	if cctx.JSONOutput {
		return cctx.Printer.PrintStructured(resp, printer.StructuredOptions{})
	}

	type saNameType struct {
		Name string `json:"name"`
		Type string `json:"type"`
	}

	var sas []saNameType
	for saName, saType := range resp.SystemAttributes {
		sas = append(sas, saNameType{
			Name: saName,
			Type: saType.String(),
		})
	}
	slices.SortFunc(sas, func(a, b saNameType) int { return strings.Compare(a.Name, b.Name) })

	var csa []saNameType
	for saName, saType := range resp.CustomAttributes {
		csa = append(csa, saNameType{
			Name: saName,
			Type: saType.String(),
		})
	}
	slices.SortFunc(csa, func(a, b saNameType) int { return strings.Compare(a.Name, b.Name) })
	sas = append(sas, csa...)

	return cctx.Printer.PrintStructured(sas, printer.StructuredOptions{Table: &printer.TableOptions{}})
}

package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"

	"github.com/temporalio/cli/internal/commandsgen"
)

// stringSlice implements flag.Value to support flags that may be specified
// multiple times (e.g. -input, -subdir).
type stringSlice []string

func (s *stringSlice) String() string {
	return fmt.Sprintf("%v", *s)
}

func (s *stringSlice) Set(value string) error {
	*s = append(*s, value)
	return nil
}

func main() {
	if err := run(); err != nil {
		log.Fatal(err)
	}
}

func run() error {
	var (
		outputDir  string
		inputFiles stringSlice
		subdirs    stringSlice
	)

	flag.Var(&inputFiles, "input", "Input YAML file (can be specified multiple times)")
	flag.StringVar(&outputDir, "output", ".", "Output directory for docs")
	flag.Var(&subdirs, "subdir", "Write the subcommands of this command into a subdirectory of separate files instead of a single file (can be specified multiple times)")
	flag.Parse()

	if len(inputFiles) == 0 {
		return fmt.Errorf("-input flag is required")
	}

	var yamlInputs [][]byte
	for _, inputFile := range inputFiles {
		data, err := os.ReadFile(inputFile)
		if err != nil {
			return fmt.Errorf("failed reading input %s: %w", inputFile, err)
		}
		yamlInputs = append(yamlInputs, data)
	}

	if err := os.MkdirAll(outputDir, 0755); err != nil {
		return fmt.Errorf("failed creating output directory: %w", err)
	}

	cmds, err := commandsgen.ParseCommands(yamlInputs...)
	if err != nil {
		return fmt.Errorf("failed parsing YAML: %w", err)
	}

	docs, err := commandsgen.GenerateDocsFiles(cmds, subdirs)
	if err != nil {
		return fmt.Errorf("failed generating docs: %w", err)
	}

	for filename, content := range docs {
		filePath := filepath.Join(outputDir, filename+".mdx")
		// Filenames may contain a path separator (e.g. "cloud/namespace") when
		// -subdir is used, so ensure the parent directory exists.
		if err := os.MkdirAll(filepath.Dir(filePath), 0755); err != nil {
			return fmt.Errorf("failed creating directory for %s: %w", filePath, err)
		}
		if err := os.WriteFile(filePath, content, 0644); err != nil {
			return fmt.Errorf("failed writing %s: %w", filePath, err)
		}
	}

	return nil
}

